function symbol(kind){return '<svg class="support-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(paths[kind]||paths.strength)+'"/></svg>';}
function states(card){return (card&&card.actionStates||[]).filter(function(s){return Object.hasOwn(definitions,s.kind);});}
